package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;
import static org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeFactorizedQuoteTest.coveringProfile;
import static org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeFactorizedQuoteTest.edge;
import static org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeFactorizedQuoteTest.row;
import static org.mockito.AdditionalAnswers.delegatesTo;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;

import java.util.OptionalLong;

import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeCostVector.Feature;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeFanOutFactsTest.StatsSource;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativePackedFtreeQuote.Site;
import org.junit.jupiter.api.Test;

class LmdbNativePackedFtreeRootUnaryQuoteTest {

	@Test
	void anAdditionalServedRootUnaryConstraintCostsOneProbePerRootLane() {
		NativeLmdbQuerySource source = source(true);
		LmdbNativeCostVector baseline = quote(source, false).total();
		LmdbNativeCostVector constrained = quote(source, true).total();
		assertThat(constrained.expected(Feature.INDEX_SEEK) - baseline.expected(Feature.INDEX_SEEK))
				.isEqualTo(500D);
		assertThat(constrained.expected(Feature.SCANNED_ROW) - baseline.expected(Feature.SCANNED_ROW))
				.isEqualTo(500D);
	}

	@Test
	void anUnservedRootUnaryConstraintCostsOneStoreCursorPerRootLane() {
		NativeLmdbQuerySource source = source(false);
		LmdbNativeCostVector baseline = quote(source, false).total();
		LmdbNativeCostVector constrained = quote(source, true).total();
		assertThat(constrained.expected(Feature.INDEX_SEEK) - baseline.expected(Feature.INDEX_SEEK))
				.isEqualTo(500D);
		assertThat(constrained.expected(Feature.BRANCH_OPEN) - baseline.expected(Feature.BRANCH_OPEN))
				.isEqualTo(500D);
	}

	@Test
	void theUnarySeedAlreadyCoveredByTheRootProducerIsNotProbedTwice() {
		LmdbNativeCostQuote quote = quote(source(true), false);
		// One seed seek, then the two child relations are each bound once per root lane. The seed relation's
		// membership and multiplicity are already carried by RunRootProducer and must not be charged again.
		assertThat(quote.total().expected(Feature.INDEX_SEEK)).isEqualTo(1D + 2D * 500D);
	}

	private static NativeLmdbQuerySource source(boolean extraUnaryServed) {
		StatsSource statistics = new StatsSource(100_000L)
				.predicate(1L, 3D, 3_000L)
				.predicate(2L, 3D, 3_000L)
				.predicate(3L, 1D, 500L)
				.predicateByObject(3L, 500D, 1L)
				.predicate(4L, 1D, 800L)
				.predicateByObject(4L, 800D, 1L)
				.adjacencyServed(true);
		NativeLmdbQuerySource source = mock(NativeLmdbQuerySource.class, delegatesTo(statistics));
		doReturn(OptionalLong.of(500L)).when(source).exactDegree(3L, 42L, false);
		doReturn(OptionalLong.of(800L)).when(source).exactDegree(4L, 43L, false);
		if (!extraUnaryServed) {
			doReturn(OptionalLong.empty()).when(source).adjacencyKeyDomainCardinality(4L, true);
		}
		return source;
	}

	private static LmdbNativeCostQuote quote(NativeLmdbQuerySource source, boolean additionalUnary) {
		RowState row = row(source);
		try {
			PatternPlan seed = unary(3L, 42L, 500D);
			PatternPlan[] patterns = additionalUnary
					? new PatternPlan[] { edge(0, 1L, 1, 9_000D), edge(0, 2L, 2, 9_000D), seed,
							unary(4L, 43L, 800D) }
					: new PatternPlan[] { edge(0, 1L, 1, 9_000D), edge(0, 2L, 2, 9_000D), seed };
			LmdbNativePackedFtree.Plan plan = LmdbNativePackedFtree.Planner.plan(
					new MultiJoinPlan(patterns, new MaskedFilter[0]), row, new int[] { 0, 1, 2 });
			assertThat(plan).isNotNull();
			assertThat(plan.root.slot).isZero();
			assertThat(plan.root.seed.pattern).isSameAs(seed);
			LmdbNativeCostQuote quote = LmdbNativePackedFtreeQuote.quote(plan, row, Site.ROWS, 0L, 4_500D);
			assertThat(quote).isNotNull();
			return quote;
		} finally {
			row.memoryScope.close();
		}
	}

	private static PatternPlan unary(long predicate, long object, double rows) {
		return new PatternPlan(Term.slot(0), Term.constant(predicate), Term.constant(object), Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, null, "", null, rows, coveringProfile(100_000L));
	}
}
